// Get the raw Gemini response JSON from the previous node
const response = $json;

// Safely extract the text field
const textOutput =
  response?.candidates?.[0]?.content?.parts?.[0]?.text;

if (!textOutput) {
  throw new Error('No text output found in Gemini response');
}

// Parse the text (it is a JSON string)
let parsed;
console.log(`textOutput=${textOutput}`)
try {
  parsed = JSON.parse(textOutput);
} catch (err) {
  throw new Error('Failed to parse Gemini text output as JSON');
}

// Return parsed JSON so n8n can use it downstream
return parsed;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const data =  $input.first().json.data.resultJson
const urlDict = JSON.parse(data)
console.log('urlDict =', urlDict);
console.log('urlDict["resultUrls"][0] =', urlDict.resultUrls[0])

return urlDict;

